out={'status':'UNPOSITIONED_PACK_ENVELOPE_NOT_ASSEMBLY','battery':r['selected_model'],'source_record':str(source),'source_record_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'manufacturer_pdf_url':m['url'],'manufacturer_pdf_sha256':hashlib.sha256(pdf.read_bytes()).hexdigest(),'local_pdf':pdf.name,'drawing_page9_visually_checked':True,'dimensions_max_mm':dims,'lead_length_mm':m['lead_length_mm'],'lead_tolerance_mm':m['lead_tolerance_mm'],'output':f.name,'output_sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'reimport_valid':True,'limitations':['Cuboid pack envelope only; no wires, connector, insulation, retention or expansion allowance.','Source values checked against local manufacturer PDF drawing; not physical measurement.','No final case-fit claim.']};(O/'battery-envelope-review.json').write_text(json.dumps(out,indent=2)+'\n');print(dims)
